Sound implementation details:

```js
const Sound = {
 ctx:null, master:null, drone:null, muted:false,
 init(){
  if (this.ctx) { this.ctx.resume?.(); return; }
  try {
   const AC = window.AudioContext || window.webkitAudioContext;
   if(!AC) return;
   const ac = new AC();
   const master = ac.createGain(); master.gain.value = this.muted?0:0.55; master.connect(ac.destination);
   this.ctx=ac; this.master=master;
   // ambient
   const droneGain=ac.createGain(); droneGain.gain.value=0.05; droneGain.connect(master); this.droneGain=droneGain;
   [55,82.5].forEach((f,i)=>{ const o=ac.createOscillator(); o.type=i?'sine':'triangle'; o.frequency.value=f; const g=ac.createGain(); g.gain.value=i?.35:.5; const lp=ac.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=200; o.connect(g).connect(lp).connect(droneGain); o.start(); });
   const lfo=ac.createOscillator(); lfo.frequency.value=.07; const lg=ac.createGain(); lg.gain.value=.025; lfo.connect(lg).connect(droneGain.gain); lfo.start();
   // noise buffer
   const len=ac.sampleRate*1; const buf=ac.createBuffer(1,len,ac.sampleRate); const data=buf.getChannelData(0); for(...) data[i]=Math.random()*2-1; this.noiseBuf=buf;
   // wind
   const src=ac.createBufferSource(); src.buffer=buf; src.loop=true;
   const bp=ac.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=700; bp.Q.value=.6;
   const ng=ac.createGain(); ng.gain.value=.012;
   src.connect(bp).connect(ng).connect(master); src.start();
  } catch(e) {}
 },
 resume(){ this.ctx?.resume?.(); },
 setMuted(m){...},
 tone(f0,f1,dur,type='sine',vol=.1,delay=0){
  if(!this.ctx||this.muted) return;
  const ac=this.ctx, t0=ac.currentTime+delay;
  const o=ac.createOscillator(), g=ac.createGain();
  o.type=type; o.frequency.setValueAtTime(Math.max(20,f0),t0);
  o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t0+dur);
  g.gain.setValueAtTime(0.0001,t0);
  g.gain.exponentialRampToValueAtTime(vol,t0+0.008);
  g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
  o.connect(g).connect(this.master); o.start(t0); o.stop(t0+dur+.02);
 },
 noise(dur=.1,vol=.1,freq=1200,q=1,delay=0){...}
```
