import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, args: ['--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding'] })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()) })
await page.goto('http://localhost:3002/')
await page.getByRole('button', { name: 'PLAY', exact: true }).click()
const log = async (label) => console.log(label, await page.evaluate(() => {
  const s = window.__chrono.state
  return { mode: s.mode, rt: +s.rt.toFixed(2), wave: s.wave, phase: s.wavePhase, enemies: s.enemies.map(e => e.kind), spawners: s.spawners.length, queue: s.spawnQueue.length, score: s.score, kills: s.kills, debt: +s.debt.toFixed(2), collections: s.collections }
}))
await page.waitForTimeout(1200)
await log('start')
for (let i = 0; i < 4; i++) {
  await page.evaluate(() => { window.__chrono.killAll(); window.__chrono.clearWave() })
  await page.waitForTimeout(3200)
  await log('after clear ' + i)
}
// Boss wave should now be active. Wait for its portal.
await page.waitForTimeout(2400)
await log('boss wave')
await page.evaluate(() => { window.__chrono.killAll() })
await page.waitForTimeout(2200)
await log('post boss kill')
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/t-win.png' })
console.log('ERRORS', errors)
await browser.close()

import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, args: ['--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding'] })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()) })
await page.goto('http://localhost:3002/')
await page.getByRole('button', { name: 'PLAY', exact: true }).click()
// Aim at nearest enemy and attack; occasionally dash away when cornered.
await page.evaluate(() => {
  const canvas = document.querySelector('#game')
  window.__bot = { aim: true, attack: true }
  const tick = () => {
    const s = window.__chrono.state
    if (s.mode !== 'playing') return
    let best = null, bd = 1e9
    for (const e of s.enemies) {
      if (e.dead) continue
      const d = Math.hypot(e.x - s.player.x, e.y - s.player.y)
      if (d < bd) { bd = d; best = e }
    }
    if (window.__bot.aim && best) {
      canvas.dispatchEvent(new MouseEvent('mousemove', { clientX: best.x, clientY: best.y, bubbles: true }))
    }
    if (window.__bot.attack) {
      window.dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true }))
    }
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
})
await page.waitForTimeout(9000)
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/t-bot.png' })
console.log('after 9s', await page.evaluate(() => { const s = window.__chrono.state; return { mode: s.mode, rt: +s.rt.toFixed(1), wave: s.wave, hp: s.player.hp, kills: s.kills, score: s.score, enemies: s.enemies.length, debt: +s.debt.toFixed(1), combo: +s.combo.toFixed(1) } }))
// Hold shift for a bit while attacking.
await page.evaluate(() => { window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Shift' })) })
await page.waitForTimeout(2600)
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/t-bot-slow.png' })
console.log('slow', await page.evaluate(() => { const s = window.__chrono.state; return { hp: s.player.hp, kills: s.kills, score: s.score, debt: +s.debt.toFixed(1), collections: s.collections, timeScale: +s.timeScale.toFixed(2), echoes: s.enemies.filter(e => e.kind === 'echo').length } }))
await page.waitForTimeout(5000)
console.log('after 17s', await page.evaluate(() => { const s = window.__chrono.state; return { mode: s.mode, wave: s.wave, hp: s.player.hp, kills: s.kills, score: s.score, enemies: s.enemies.length, debt: +s.debt.toFixed(1), collections: s.collections } }))
console.log('ERRORS', errors)
await browser.close()

