import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const measure = async (label) => {
  const v = await page.evaluate(() => new Promise(resolve => {
    const times = []; const start = performance.now()
    function tick(now) {
      times.push(now)
      if (now - start > 3000) {
        const gaps = times.slice(1).map((t, i) => +(t - times[i]).toFixed(0)).sort((a, b) => a - b)
        resolve({ fps: +(times.length / ((now - start) / 1000)).toFixed(2), gaps: gaps.slice(0, 12), max: gaps[gaps.length - 1] })
      } else requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
    setTimeout(() => resolve({ fps: 0, stuck: true, n: times.length }), 12000)
  }))
  console.log(label, JSON.stringify(v))
}
page.on('console', m => console.log('console:', m.text()))
await page.goto('data:text/html,<h1>blank</h1>')
await measure('blank-page')
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
console.log(await page.evaluate(() => ({ dpr: devicePixelRatio, hc: navigator.hardwareConcurrency, canvas: !!document.querySelector('#game') })))
await measure('our-page')
await page.evaluate(() => { document.querySelector('#game').remove() })
await measure('canvas-removed')
await page.evaluate(() => { document.querySelector('#menu').style.display = 'none' })
await measure('menu-gone')
await browser.close()

