}

async function measure(page, label) {
  const v = await page.evaluate(() => new Promise(resolve => {
    const times = []; const start = performance.now()
    function tick(now) {
      times.push(now)
      if (now - start > 2500) {
        const gaps = times.slice(1).map((t, i) => +(t - times[i]).toFixed(0)).sort((a, b) => a - b)
        resolve({ fps: +(times.length / ((now - start) / 1000)).toFixed(1), p50: gaps[Math.floor(gaps.length / 2)], max: gaps[gaps.length - 1], n: times.length })
