    samples.push([+(now).toFixed(0), r.x, r.y, r.width, r.height])
    if (++n < 12) requestAnimationFrame(tick)
    else resolve(samples)
  }
  requestAnimationFrame(tick)
})))
console.log('animation', await page.evaluate(() => {
