const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })

const variants = {
  current: { css: '', noRender: false, hideCanvas: false },
  'no-boot-render': { css: '', noRender: true },
  'no-boot+no-fx': { css: '.fx{display:none!important}', noRender: true },
  'no-boot+grain-off': { css: '.grain{display:none!important}', noRender: true },
  'no-boot+scan-off': { css: '.scanlines{display:none!important}', noRender: true },
  'no-boot+vignette-off': { css: '.vignette{display:none!important}', noRender: true },
  'no-boot+menu-flat': { css: '#menu{background:#05060c!important}', noRender: true },
  'no-boot+title-off': { css: '.title .t1,.title .t2{text-shadow:none!important;-webkit-text-stroke:0!important}.title .t2::after{display:none!important}', noRender: true },
  'no-boot+sheen-off': { css: '.btn-primary::before{display:none!important}', noRender: true },
  'hide-canvas': { css: '', noRender: true, hideCanvas: true },
  'no-boot+no-blur': { css: '.hud-block{backdrop-filter:none!important}', noRender: true },
}

for (const [name, v] of Object.entries(variants)) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  await page.addInitScript((opts) => {
    window.__longs = []
    try { new PerformanceObserver(list => { for (const e of list.getEntries()) window.__longs.push(+e.duration.toFixed(0)) }).observe({ type: 'longtask', buffered: true }) } catch {}
    if (opts.css) document.addEventListener('DOMContentLoaded', () => { const s = document.createElement('style'); s.textContent = opts.css; document.head.appendChild(s) })
  }, v)
  if (v.noRender) {
    await page.route('**/game.js', async route => {
      const res = await route.fetch()
      let body = await res.text()
      body = body.replace('  render();\n  menuFrozen = true;', '  menuFrozen = true;')
      await route.fulfill({ response: res, body })
    })
  }
  const t0 = Date.now()
  await page.goto('http://localhost:3002/', { waitUntil: 'load' })
  const loadMs = Date.now() - t0
  await page.locator('body').waitFor({ state: 'visible' })
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  const readyMs = Date.now() - t0
  if (v.hideCanvas) await page.evaluate(() => { document.querySelector('#game').style.visibility = 'hidden' })
  const data = await page.evaluate(() => new Promise(resolve => {
    const times = []; const start = performance.now()
    function tick(now) {
      times.push(+(now - start).toFixed(0))
      if (now - start > 3500) resolve({ times: times.slice(0, 12), longs: window.__longs })
      else requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }))
  console.log(name.padEnd(22), 'load', loadMs, 'ready', readyMs, JSON.stringify(data))
  await page.close()
}
await browser.close()

