}
.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

#menu {
  padding: clamp(24px, 5vw, 72px);
  align-items: center;
  background:
    linear-gradient(90deg, rgba(4, 6, 12, .97) 0%, rgba(4, 6, 12, .9) 32%, rgba(4, 6, 12, .42) 58%, rgba(4, 6, 12, 0) 78%);
}
#menu.hidden { pointer-events: none; }

.menu-inner {
  width: min(640px, 100%);
  position: relative;
  z-index: 2;
  margin-top: -2vh;
}

.kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .34em;
  color: var(--cyan);
  text-transform: uppercase;
}

.kicker-line {
  display: inline-block;
  width: 34px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 12px var(--cyan);
}

.title {
  margin: clamp(14px, 2.5vh, 26px) 0 0;
  font-family: var(--display);
  font-weight: 900;
  line-height: .78;
  letter-spacing: -.055em;
  font-size: clamp(72px, 12.6vw, 188px);
  display: flex;
  flex-direction: column;
  position: relative;
}
.title .t1 {
  color: #f2fdff;
  text-shadow: 0 0 48px rgba(97, 241, 255, .22), 4px 0 0 rgba(255, 63, 95, .12);
}
.title .t2 {
  color: transparent;
  -webkit-text-stroke: clamp(1px, .18vw, 3px) var(--amber);
  text-shadow: 0 0 40px rgba(255, 184, 77, .18);
  margin-left: .05em;
  position: relative;
}
.title .t2::after {
  content: "DEBT";
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 63, 95, .4);
  transform: translate(3px, -2px);
  opacity: .4;
  height: 58px;
  font-size: 8px;
  color: var(--cyan);
  border: 1px solid rgba(97, 241, 255, .4);
  background: radial-gradient(circle at 40% 30%, rgba(201, 253, 255, .14), rgba(97, 241, 255, .04) 65%, transparent);
}

/* ---------------------------------------------------------------- Responsive */

@media (max-width: 900px) {
  #menu { background: linear-gradient(180deg, rgba(4, 6, 12, .97) 0%, rgba(4, 6, 12, .92) 44%, rgba(4, 6, 12, .55) 72%, rgba(4, 6, 12, .25) 100%); align-items: flex-start; padding-top: max(8vh, 42px); }
  .menu-inner { margin-top: 0; }
  .title { font-size: clamp(68px, 19vw, 148px); }
  .tagline { max-width: 30ch; }
  .menu-foot { font-size: 6px; }
  .foot-mid { display: none; }
  #hints { display: none; }
  body.is-touch #hints { display: none; }
}

@media (max-width: 760px) {
  #hud { gap: 6px; padding: max(10px, env(safe-area-inset-top)) 10px 0; }
  .hud-block { padding: 6px 8px 7px; width: auto; clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 0 100%); }
  .hud-label { font-size: 7px; letter-spacing: .1em; margin-bottom: 5px; gap: 4px; }
  .hp-track { height: 9px; }
  .sub-row { display: none; }
  .debt-num span { font-size: 20px; }
  .debt-num small { font-size: 8px; }
  .debt-num em { display: none; }
  .debt-track { height: 4px; margin-top: 5px; }
  .debt-warn { font-size: 5.5px; letter-spacing: .1em; margin-top: 4px; }
  .hud-center { min-width: 62px; }
  .wave-line { font-size: 6px; gap: 3px; letter-spacing: .1em; }
  .wave-line strong { font-size: 17px; }
  .score { font-size: 12px; letter-spacing: .06em; margin-top: 1px; }
  .combo { font-size: 10px; }
  #bossHud { top: max(82px, calc(env(safe-area-inset-top) + 66px)); width: 76vw; }
  .boss-name { font-size: 6.5px; letter-spacing: .12em; gap: 6px; }
  .boss-name span { font-size: 5.5px; }
  .banner { top: 21%; }
  .banner-kicker { font-size: 8px; letter-spacing: .25em; }
  .banner-title { font-size: clamp(25px, 7.5vw, 40px); }
  .banner-sub { font-size: 7px; letter-spacing: .14em; }
  #toast { font-size: 8px; bottom: 27%; padding: 7px 10px; letter-spacing: .1em; }
  .menu-foot { left: 18px; right: 18px; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .end-rank { width: 50px; height: 50px; font-size: 26px; }
  .panel { padding: 26px 22px 28px; }
  .panel-copy { font-size: 12.5px; margin: 14px 0 24px; }
  #pause .btn-primary, #end .btn-primary { width: 100%; }
}

@media (max-height: 620px) and (orientation: landscape) {
  #menu { padding-top: 20px; align-items: center; }
  .title { font-size: clamp(52px, 13vh, 100px); margin-top: 8px; }
  .tagline { margin-top: 10px; font-size: 13px; }
  .menu-actions { margin-top: 14px; }
  .controls { margin-top: 14px; padding-top: 10px; }
  .menu-foot { display: none; }
  .banner { top: 12%; }
  .banner-title { font-size: clamp(22px, 5vh, 40px); }
}

@media (pointer: coarse) {
  body.is-touch #muteBtn { bottom: max(14px, env(safe-area-inset-bottom)); top: auto; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}

/* Touch mute stays out of the thumb zone. */
body.is-touch.is-playing #muteBtn { display: none; }

#pause, #end {
