/* CSS clock backdrop. The live canvas is paused while the menu is open, so the
   opening screen gets its arena from cheap, responsive CSS instead of a costly
   full-canvas repaint. */
.menu-clock {
  position: absolute;
  z-index: 1;
  left: 72%;
  top: 50%;
  width: min(62vw, 86vh);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(97, 241, 255, .5);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 50%, rgba(30, 92, 126, .2), rgba(13, 40, 64, .12) 56%, rgba(4, 8, 18, 0) 78%);
  box-shadow:
    0 0 34px rgba(97, 241, 255, .18),
    inset 0 0 100px rgba(18, 70, 100, .24);
  pointer-events: none;
  opacity: .92;
}
.menu-clock::before {
  content: "";
  position: absolute;
  inset: 2.6%;
  border: 1px dashed rgba(170, 245, 255, .26);
  border-radius: 50%;
}
.menu-clock::after {
  content: "";
  position: absolute;
  inset: -2.4%;
  border: 1px solid rgba(97, 241, 255, .1);
  border-radius: 50%;
}
.mc-grid {
  position: absolute;
  inset: 1px;
  border-radius: 50%;
  overflow: hidden;
  opacity: .55;
  background:
    repeating-linear-gradient(0deg, rgba(88, 210, 240, .07) 0 1px, transparent 1px 58px),
    repeating-linear-gradient(90deg, rgba(88, 210, 240, .07) 0 1px, transparent 1px 58px);
}
.mc-ring {
