const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true })
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.waitForTimeout(2000)
for (const [x, y] of [[200, 320], [200, 500], [340, 500], [15, 500]]) {
  console.log(x, y, await page.evaluate(([x, y]) => document.elementsFromPoint(x, y).slice(0, 6).map(e => e.tagName + (e.id ? '#' + e.id : '') + (e.className && typeof e.className === 'string' ? '.' + e.className.split(' ').join('.') : '') + '|' + getComputedStyle(e).backgroundColor + '|' + getComputedStyle(e).opacity), [x, y]))
}
console.log('clock', await page.evaluate(() => { const c = document.querySelector('.menu-clock'); const r = c.getBoundingClientRect(); return { r: r.toJSON(), z: getComputedStyle(c).zIndex, op: getComputedStyle(c).opacity, bg: getComputedStyle(c).backgroundImage } }))
console.log('inner', await page.evaluate(() => { const c = document.querySelector('.menu-inner'); const r = c.getBoundingClientRect(); return { r: r.toJSON(), z: getComputedStyle(c).zIndex, bg: getComputedStyle(c).backgroundColor, bs: getComputedStyle(c).boxShadow, filter: getComputedStyle(c).filter } }))
await browser.close()

