import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })

const variants = {
  current: '',
  'clock-hidden': '.menu-clock{display:none!important}',
  'no-drop-shadow': '.mc-chevron,.mc-echo{filter:none!important}',
  'no-anim': '.menu-clock *{animation:none!important}',
  'no-opacity': '.menu-clock{opacity:1!important}',
  'no-grid': '.mc-grid{display:none!important}',
  'no-box-shadow': '.menu-clock{box-shadow:none!important}',
  'no-pseudo': '.menu-clock::before,.menu-clock::after{display:none!important}',
  'simple': '.menu-clock{background:#05060c!important;box-shadow:none!important}.menu-clock::before,.menu-clock::after,.mc-grid,.mc-ring,.mc-hand{display:none!important}.mc-chevron,.mc-echo{filter:none!important;animation:none!important}',
  'no-fx': '.fx{display:none!important}',
  'no-fx-clock': '.fx{display:none!important}.menu-clock{display:none!important}',
}

for (const [name, css] of Object.entries(variants)) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  await page.addInitScript((css) => {
    document.addEventListener('DOMContentLoaded', () => { const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s) })
  }, css)
  const t0 = Date.now()
  await page.goto('http://localhost:3002/', { waitUntil: 'load' })
  const loadMs = Date.now() - t0
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  const readyMs = Date.now() - t0
  const data = await page.evaluate(() => new Promise(resolve => {
    const times = []; const start = performance.now()
    function tick(now) {
      times.push(+(now - start).toFixed(0))
      if (now - start > 3000) resolve(times.slice(0, 10))
      else requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }))
  console.log(name.padEnd(18), 'load', loadMs, 'ready', readyMs, JSON.stringify(data))
  await page.close()
}
await browser.close()

