  box-shadow: 0 0 14px rgba(255, 184, 77, .5);
  transition: width .12s linear;
}

.debt-ticks { background-image: repeating-linear-gradient(90deg, transparent 0 calc(25% - 1px), rgba(5, 7, 12, .85) calc(25% - 1px) 25%); }

.debt-warn {
  margin-top: 6px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .19em;
  color: rgba(255, 184, 77, .35);
  text-transform: uppercase;
  transition: color .2s;
  white-space: nowrap;
}

.debt-block.warn {
  border-color: rgba(255, 63, 95, .55);
  border-top-color: var(--red);
  box-shadow: 0 0 26px rgba(255, 63, 95, .15), inset 0 0 22px rgba(255, 63, 95, .06);
}
.debt-block.warn .debt-warn { color: var(--red); animation: blink .55s steps(1) infinite; }
.debt-block.warn .debt-num span { color: var(--red); }

@keyframes blink { 50% { opacity: .25; } }

/* Boss bar */
#bossHud {
  position: absolute;
  z-index: 6;
  top: max(104px, calc(env(safe-area-inset-top) + 84px));
  left: 50%;
  transform: translate(-50%, -6px);
  width: min(560px, 68vw);
  opacity: 0;
  pointer-events: none;
  transition: opacity .4s, transform .4s;
}
#bossHud.on { opacity: 1; transform: translate(-50%, 0); }

.boss-name {
  display: flex;
  justify-content: center;
  gap: 12px;
  align-items: baseline;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .24em;
  color: var(--red);
  text-shadow: 0 0 12px rgba(255, 63, 95, .5);
  margin-bottom: 5px;
}
.boss-name span { color: var(--faint); font-size: 7px; letter-spacing: .2em; }

.boss-track {
  position: relative;
  height: 7px;
  background: rgba(0, 0, 0, .6);
  border: 1px solid rgba(255, 63, 95, .35);
  overflow: hidden;
}
.boss-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #7a1527, var(--red) 55%, var(--amber));
  box-shadow: 0 0 18px rgba(255, 63, 95, .7);
  transition: width .15s;
}
.boss-segs { background-image: repeating-linear-gradient(90deg, transparent 0 calc(10% - 1px), rgba(5, 7, 12, .9) calc(10% - 1px) 10%); }

/* Banner */
.banner {
  position: absolute;
  z-index: 7;
  top: 17%;
  left: 50%;
  transform: translate(-50%, 8px);
  width: min(900px, 92vw);
  text-align: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity .35s ease, transform .5s cubic-bezier(.2, .8, .2, 1);
  text-shadow: 0 4px 30px rgba(0, 0, 0, .9);
}
.banner.on { opacity: 1; transform: translate(-50%, 0); }
.banner-kicker {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .42em;
  color: var(--cyan);
  margin-bottom: 8px;
}
.banner-title {
  font-family: var(--display);
  font-size: clamp(28px, 4.6vw, 62px);
  line-height: .92;
  letter-spacing: -.02em;
  text-transform: uppercase;
  color: var(--ink);
  -webkit-text-stroke: 1px rgba(255, 255, 255, .15);
}
.banner-sub {
  margin-top: 9px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .22em;
  color: var(--muted);
  text-transform: uppercase;
}
.banner.danger .banner-kicker { color: var(--red); }
.banner.danger .banner-title { color: #fff; text-shadow: 0 0 34px rgba(255, 63, 95, .8); -webkit-text-stroke-color: var(--red); }
.banner.danger .banner-sub { color: rgba(255, 130, 145, .9); }
.banner.gold .banner-kicker { color: var(--amber); }
.banner.gold .banner-title { color: var(--amber-hot); -webkit-text-stroke-color: var(--amber); }

/* Toast */
#toast {
  position: absolute;
  z-index: 7;
  left: 50%;
  bottom: 15%;
  transform: translate(-50%, 6px);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .18em;
  color: var(--ink);
  background: rgba(6, 10, 20, .78);
  border: 1px solid rgba(97, 241, 255, .22);
  padding: 8px 14px;
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s, transform .25s;
  white-space: nowrap;
  max-width: 90vw;
  overflow: hidden;
  text-overflow: ellipsis;
}
#toast.on { opacity: 1; transform: translate(-50%, 0); }
#toast.gold { color: var(--amber-hot); border-color: rgba(255, 184, 77, .4); }
#toast.danger { color: #ffd9de; border-color: rgba(255, 63, 95, .5); background: rgba(28, 5, 11, .82); }

/* Hints */
#hints {
  position: absolute;
  z-index: 6;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  gap: 18px;
  align-items: center;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .16em;
  color: rgba(118, 144, 166, .72);
  pointer-events: none;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .4s;
}
body.is-playing #hints { opacity: 1; }
#hints span { display: inline-flex; gap: 6px; align-items: center; }
#hints .hint-steal { color: var(--amber); }

kbd {
  display: inline-block;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .06em;
  color: var(--ink);
  background: rgba(255, 255, 255, .06);
  border: 1px solid rgba(255, 255, 255, .14);
  border-bottom-color: rgba(255, 255, 255, .26);
  padding: 3px 5px;
  line-height: 1;
}

/* Mute */
#muteBtn {
  position: absolute;
  z-index: 12;
  top: max(20px, env(safe-area-inset-top));
  right: max(18px, env(safe-area-inset-right));
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .16em;
  color: var(--faint);
  padding: 7px 9px;
  border: 1px solid rgba(255, 255, 255, .09);
  background: rgba(6, 10, 18, .55);
  transition: color .2s, border-color .2s;
}
#muteBtn:hover { color: var(--cyan); border-color: var(--line); }
body.is-playing #muteBtn { top: auto; bottom: max(14px, env(safe-area-inset-bottom)); right: 18px; opacity: .5; }
body.is-playing #muteBtn:hover { opacity: 1; }
body.is-menu #muteBtn { top: auto; bottom: max(18px, env(safe-area-inset-bottom)); right: max(18px, env(safe-area-inset-right)); }

/* ---------------------------------------------------------------- Screens */

.screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  opacity: 1;
  visibility: visible;
  transition: opacity .38s ease, visibility .38s ease;
}

input.content:
import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })

const hideOthers = '#hud,#bossHud,#banner,#toast,#hints,#touch,#muteBtn,#pause,#end{display:none!important}'
const variants = {
  current: '',
  'hide-others': hideOthers,
  'hide-others-clock': hideOthers + '.menu-clock{display:none!important}',
  'hide-others-inner': hideOthers + '.menu-inner{display:none!important}',
  'hide-others-fx': hideOthers + '.fx{display:none!important}',
  'only-menu-bare': hideOthers + '.fx,.menu-clock{display:none!important}#menu{background:#05060c!important}.menu-inner,.menu-foot{display:none!important}',
  'no-app-bg': '#app{background:transparent!important}',
  'no-screen-transition': '.screen{transition:none!important}',
}
for (const [name, css] of Object.entries(variants)) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  await page.addInitScript((css) => {
    document.addEventListener('DOMContentLoaded', () => { const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s) })
  }, css)
  const t0 = Date.now()
  await page.goto('http://localhost:3002/', { waitUntil: 'load' })
  const loadMs = Date.now() - t0
  await page.waitForFunction(() => document.fonts.status === 'loaded')
  const readyMs = Date.now() - t0
  const data = await page.evaluate(() => new Promise(resolve => {
    const times = []; const start = performance.now()
    function tick(now) {
      times.push(+(now - start).toFixed(0))
      if (now - start > 3000) resolve(times.slice(0, 10))
      else requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }))
  console.log(name.padEnd(22), 'load', loadMs, 'ready', readyMs, JSON.stringify(data))
  await page.close()
}
await browser.close()

