let last = performance.now();
function frame(now) {
  const dt = clamp((now - last) / 1000, 0, 0.05);
  last = now;
  // The menu scene is a still frame; keeping it static avoids redrawing the
  // full arena every tick, which can starve the main thread on software
  // renderers and delay the first interaction.
  if (state.mode === 'menu' && menuFrozen) {
    requestAnimationFrame(frame);
    return;
  }
  update(dt);
  render();
  if (state.mode === 'menu') menuFrozen = true;
  requestAnimationFrame(frame);
}

